def parse_dt(s):
    if not s:
        return None
    try:
        # handle trailing Z
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        try:
            return datetime.strptime(s, '%Y-%m-%dT%H:%M:%S')
        except Exception:
            return None

